ulong opaqueNormal=30;backend.UploadTexture(30,1,1,0,new byte[]{128,128,255,64},false);var diagnosticLightBackup=light;light.SunLightDirection=Vector3.Forward;light.SunColorRaw=light.SunSpecularColorRaw=Vector3.One;light.SunDiffuseFactor=light.SunSpecularFactor=1;
