NativeBillboardDraw Billboard(uint flags,uint bucket,float z=-2){var data=new byte[48];Buffer.BlockCopy(new[]{.8f,.2f,0,.5f},0,data,0,16);Buffer.BlockCopy(BitConverter.GetBytes(-1),0,data,16,4);Buffer.BlockCopy(new[]{0f,0,.1f,0,0,1,1},0,data,20,28);return new NativeBillboardDraw{Texture=3,Flags=flags,Bucket=bucket,Data=data,Vertices=new[]{-.7f,.7f,z,0,0,.7f,.7f,z,1,0,.7f,-.7f,z,1,1,-.7f,-.7f,z,0,1}};}
